import{_ as n,C as i,c as s,o as r,aj as l,G as t,w as d}from"./chunks/framework.Bfdr4H5E.js";const w=JSON.parse('{"title":"Money Management – Explanatory Notes","description":"","frontmatter":{"outline":"deep","prev":{"text":"Money Management – Trading Plan Inclusion","link":"/trading-with-pav/money-management-trading-plan-inclusion"},"next":{"text":"Contingency Management","link":"/trading-with-pav/contingency-management"}},"headers":[],"relativePath":"trading-with-pav/money-management-explanatory-notes.md","filePath":"trading-with-pav/money-management-explanatory-notes.md"}'),m={name:"trading-with-pav/money-management-explanatory-notes.md"};function u(h,e,p,c,y,g){const a=i("GraphComment"),o=i("ClientOnly");return r(),s("div",null,[e[0]||(e[0]=l('<h1 id="money-management-–-explanatory-notes" tabindex="-1">Money Management – Explanatory Notes <a class="header-anchor" href="#money-management-–-explanatory-notes" aria-label="Permalink to &quot;Money Management – Explanatory Notes&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#money-management-–-explanatory-notes-1">Money Management – Explanatory Notes</a><ul><li><a href="#individual-trade-risk">Individual Trade Risk:</a></li><li><a href="#session-money-management-session-draw-down-risk">Session Money Management: “Session Draw-down Risk”</a></li><li><a href="#business-money-management-business-draw-down-risk">Business Money Management: “Business Draw-down Risk”</a></li><li><a href="#a-graduated-approach-to-increasing-size-increased-size-risk">A Graduated Approach to Increasing Size: “Increased Size Risk”</a></li><li><a href="#income-to-maintain-lifestyle-insufficient-income-risk">Income to Maintain Lifestyle: “Insufficient Income Risk”</a></li></ul></li><li><a href="#additional-considerations-–-higher-timeframe-multiple-markets">Additional Considerations – Higher Timeframe / Multiple Markets</a></li><li><a href="#money-management-–-wrap-up">Money Management – Wrap Up</a></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="money-management-–-explanatory-notes-1" tabindex="-1">Money Management – <strong>Explanatory Notes</strong> <a class="header-anchor" href="#money-management-–-explanatory-notes-1" aria-label="Permalink to &quot;Money Management – **Explanatory Notes**&quot;">​</a></h2><p>Below is Money Management – <strong>Explanatory Notes</strong> for <a href="/sk/trading-with-pav/money-management-trading-plan-inclusion/">Money Management – Trading Plan Inclusion</a>.</p><h3 id="individual-trade-risk" tabindex="-1">Individual Trade Risk: <a class="header-anchor" href="#individual-trade-risk" aria-label="Permalink to &quot;Individual Trade Risk:&quot;">​</a></h3><ul><li>Treatments must be applied to our trading plan to ensure that no single loss can threaten the survival of our trading business.</li><li>Individual trade risk will be managed through the use of stop-loss orders and position sizing, such that <strong>individual trade risk will not exceed 1% of equity</strong>.</li><li>Most educators recommend varying levels between 1% and 5%, with the majority recommending 2%. <ul><li>We recommend 1% maximum.</li><li>2% is too great in my opinion during the learning process.</li><li>If you have five full-size losses in a row, which will happen while learning, you have lost 10% of your account.</li><li>In my experience, this is too great a loss over too short a period of time for new traders, who still have not developed trust in their strategy or themselves.</li></ul></li><li>Experiment with greater risk if you wish, AFTER having proven consistent profitability.</li><li>For NOW, Individual trade risk must be no greater than 1%.</li><li>Note: When trading in 2 part positions, the maximum risk per part must therefore be 0.5%.</li><li>Under NO circumstances will you allow a trade to continue past its stop loss point.</li><li>Price hitting your stop means that either your trade idea was wrong or your timing was wrong.</li><li>Either way, you need to be out in order to contain any risk.</li><li>One final word of warning! <ul><li>Please note that limiting risk through the use of stop losses does not guarantee the risk is limited to that amount.</li><li>In most markets a stop loss order when triggered generates a market order designed to exit you from your position.</li><li>In Intraday conditions of extreme market panic there may not be any orders taking the opposite side of your market order.</li><li>Significant slippage can occur. A lot of traders lost a lot of money.</li><li>Be familiar with exactly how your broker executes and manages their orders. And accept that there will always be risk in the markets.</li><li>Hence the often provided disclaimer that you should only ever trade with money you can afford to entirely lose.</li></ul></li><li>That being said, the 1% individual trade risk will provide a significant buffer of safety should you find yourself positioned against one of these extremely rare market events.</li></ul><h3 id="session-money-management-session-draw-down-risk" tabindex="-1">Session Money Management: “Session Draw-down Risk” <a class="header-anchor" href="#session-money-management-session-draw-down-risk" aria-label="Permalink to &quot;Session Money Management: “Session Draw-down Risk”&quot;">​</a></h3><ul><li>Treatments must be applied to our trading plan to ensure that no 1 trading session draw-down can threaten the survival of our trading business. <ul><li>While our 1% maximum individual trade risk will assist here in slowing any rate of draw-down, our session survival can still be threatened through poor personal management.</li><li>Such examples would include over-trading or revenge trading; desperately continuing to trade when in draw-down in order to salvage something out of the session.</li><li>This will rarely ever work. Quite likely the initial draw-down is a result of poor market read or negative psychological influences.</li><li>Our attempts to recover the session will be even further impacted by worse market read and psychological influences, as our perceptual abilities and decision making are impaired through fear of loss.</li></ul></li><li><strong>I recommend implementing a &quot;timeout&quot; at 2% session draw-down</strong>. <ul><li>This is fairly small amount, but two full-size losses are a warning that perhaps you are not in sync with the market, or there are some external or internal distracters impacting your ability to execute your plan.</li><li>Take a short break; then review the session so far.</li><li>Continue only if you can confirm that the trades were appropriately selected, entered and managed in accordance with your plan; or if you identify errors and correct them.</li><li>Note that 2% draw-down does not just mean 2 stop-outs.</li><li>With an active trade management process, many stops will occur with reduced loss.</li><li>It may take you 2, 3, 4, 5 or even more trades to hit a 2% session draw-down.</li></ul></li><li><strong>We recommend implementing a 3% session draw-down compulsory stop</strong>. <ul><li>Something is not right. Walk away. Review at a later time.</li><li>Capital has been saved to allow you to continue next session.</li></ul></li><li>The figures for 2% session timeout and 3% session stop are of course just recommended.</li><li>I acknowledge however that they are very tight.</li><li>If you are comfortable with more risk then you can increase these limits.</li><li>We would recommend waiting till consistent profitability is proven first.</li><li>Please though, not more than 3% session timeout and 5% session stop.</li><li>Take some time out to reassess and start fresh next session.</li><li>Your session P&amp;L must operate with a session trailing stop. <ul><li>Do not get off to a great start in this session and then give back all your profits as you trade your way back down to your maximum session stop.</li><li>Like we do with individual trades, we will implement a session trailing stop.</li><li>We recommend the same parameters we use for initial stops. Trail your session timeout 2%. Trail your session stop 3%.</li></ul></li></ul><p>Let’s look at an example:</p><ul><li>Equity Balance ₹20,000</li><li>Individual trade risk: ₹200 (1%)</li><li>(Note. Trading two parts will require max ₹100 risk per part)</li><li>Trading session timeout:</li><li>Initial timeout at ₹400 (2%), trailing ₹400 below session equity highs.</li><li>Trading session stop:</li><li>Initial stop ₹600 (3%), trailing ₹600 below Intraday session equity highs.</li></ul><h3 id="business-money-management-business-draw-down-risk" tabindex="-1">Business Money Management: “Business Draw-down Risk” <a class="header-anchor" href="#business-money-management-business-draw-down-risk" aria-label="Permalink to &quot;Business Money Management: “Business Draw-down Risk”&quot;">​</a></h3><ul><li>Treatments must be applied to our trading plan to ensure that we stop trading at a certain level of draw-down and halt any further erosion of our balance.</li><li><strong>We recommend a stop at 20% draw-down</strong>. <ul><li>At this point, something is not going right.</li><li>If you want more, then at the absolute most do not go beyond 30% draw-down.</li><li>Beyond this it becomes more difficult to regain the losses.</li></ul></li><li>Take some time out to again study this document. Review your trading performance with the benefit of hindsight and return to simulation trading, until consistent profitability is again proven.</li><li>New traders, with small account balances, should use this time out of the markets to replenish their account from other income sources, and should not start trading live again until the account balance is back to its original level.</li></ul><h3 id="a-graduated-approach-to-increasing-size-increased-size-risk" tabindex="-1">A Graduated Approach to Increasing Size: “Increased Size Risk” <a class="header-anchor" href="#a-graduated-approach-to-increasing-size-increased-size-risk" aria-label="Permalink to &quot;A Graduated Approach to Increasing Size: “Increased Size Risk”&quot;">​</a></h3><ul><li>Size can only be increased as allowed by our percentage risk rule.</li><li>As the number of contracts traded increases, you will reach levels beyond which the rupee/dollar risk is psychologically more and more difficult to accept.</li><li>This will act as a source of fear to impact upon your trading results.</li><li>We will therefore implement a graduated approach to increasing size.</li><li>Success at the current size must be proven via at least one month of profitable trading.</li><li><strong>All size increases must be proven in a simulation environment first</strong>.</li><li>My preference is to see a profitable week, before returning to the live environment.</li><li>This may be done via market replay out of hours, in order to speed up the process.</li><li>If a session stop is hit while live trading, you should consider the need to return to the previous size and/or the sim environment.</li><li>If 2 session stops are hit, then you must return to the previous size.</li></ul><h3 id="income-to-maintain-lifestyle-insufficient-income-risk" tabindex="-1">Income to Maintain Lifestyle: “Insufficient Income Risk” <a class="header-anchor" href="#income-to-maintain-lifestyle-insufficient-income-risk" aria-label="Permalink to &quot;Income to Maintain Lifestyle: “Insufficient Income Risk”&quot;">​</a></h3><ul><li><p>The timeframe to consistent profitability is unknown; varying for each individual.</p></li><li><p>So our financial survival plan needs to last as long as is necessary for us to achieve this goal.</p></li><li><p>Too many books offer the suggestion of saving sufficient funds to allow you to survive for at least 12 months of live trading.</p></li><li><p>This implies that 12 months will be sufficient time to achieve profitability.</p><ul><li>Rubbish.</li></ul></li><li><p>What if it takes you 13 months?</p></li><li><p>What if it takes you 2 years?</p></li><li><p>A better plan is to ensure financial survival for as long as is necessary to achieve your end goal.</p></li><li><p>Until you have achieved consistent profitability, any funds withdrawn from your trading account to fund lifestyle expenses place your trading business at risk.</p></li><li><p>A wiser plan is to therefore structure yourself such that you do not require any trading profits for lifestyle.</p></li><li><p>If sufficient alternate income streams are currently available, such as through your spouse’s income and investment or business income, then you are free to trade full-time while developing your skills.</p></li><li><p>If sufficient alternate income streams are NOT available, and trading has not yet developed to a level of consistent profitability such that profits allow both capital growth and withdrawal,</p></li><li><p>then you cannot yet trade full-time.</p></li><li><p>It may not seem fair, but the reality is what it is. You need to:</p><ul><li>Continue working in order to support your family and lifestyle.</li><li>Identify means of developing as a trader, around your work and life.</li><li>While this is easier said than done, it can be achieved.</li></ul></li><li><p>Consider options to limit your trading time to a maximum of 2-3 hours per day, such as via longer timeframes (e.g. daily charts), or day-trading only the opening session of a market or the open of your favorite commodity contract. With markets open 13 hours a day, there will be something available at a time to suit you.</p></li></ul><h2 id="additional-considerations-–-higher-timeframe-multiple-markets" tabindex="-1">Additional Considerations – Higher Timeframe / Multiple Markets <a class="header-anchor" href="#additional-considerations-–-higher-timeframe-multiple-markets" aria-label="Permalink to &quot;Additional Considerations – Higher Timeframe / Multiple Markets&quot;">​</a></h2><p>Higher timeframe traders will usually have multiple positions open at one time. This incurs an additional risk not faced by short timeframe day-traders such as myself – multiple position risk; an unexpected news event or market shock which stops out all positions at once.</p><ul><li><strong>Multiple position exposure must be limited to no more than 3%</strong>.</li><li>This does not necessarily mean you limit your portfolio to only 3 positions. You may wish to risk six positions at 0.5% risk per trade. Alternatively you may be willing to add additional positions as current positions move their stop to break-even or beyond, accepting that there is no longer an account draw-down risk with these trades.</li><li>In addition, take care to ensure that multiple positions are not in highly-correlated markets. Unless you actively monitor market correlations and identify suitable conditions for these trades, it’s best to just avoid highly correlated markets.</li></ul><p>An additional consideration is the need to redefine the term “session”. In previous discussion, session timeout and stop limits related to my own day-trading, referring to one trading period, or one day.</p><p>For longer timeframe traders this won’t be applicable, as your trades will often extend greater than one day. Redefine a trading session to whatever is applicable to your circumstances.</p><p>For example, you may wish to define timeout and stop criteria per week.</p><h2 id="money-management-–-wrap-up" tabindex="-1">Money Management – Wrap Up <a class="header-anchor" href="#money-management-–-wrap-up" aria-label="Permalink to &quot;Money Management – Wrap Up&quot;">​</a></h2><p>Some final points to wrap up money management…</p><p>There’s a great difference between the session stop level of 3% and the business stop level of 20%. Some of you may wish to implement an intermediate level, such as a Weekly or Monthly percentages for timeout and stop. I don’t, as I’m typically aware of the fact that something is wrong and am able to conduct a review anyway, despite not mandating any stop levels. However it may be something you wish to consider.</p><p>And most importantly… I know some of you will not have sufficient funds to trade with a maximum of 1% risk. If that’s the case, then rather than accepting additional risk, I recommend you continue with simulation trading only while saving additional capital, or find a market or timeframe which allows this level of risk.</p><p>Money management can be quite complex if you wish it to be so. My preference is to make it as simple as possible. Avoid all mathematical models such as “Optimal f” or the “Kelly Criterion”. Stick to a simple approach.</p><p>The focus for most of you will not be capital growth, but capital preservation during the learning phase. So make it simple and make it safe. Minimize the potential for career-ending drawdown. Stick to a low percent risk model.</p><p>Once consistently profitable, if you wish to increase risk in search of higher gains then by all means do some research on alternate money management strategies. I don’t recommend it though. For me, simplicity is always the best.</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',30)),t(o,null,{default:d(()=>[t(a)]),_:1})])}const k=n(m,[["render",u]]);export{w as __pageData,k as default};
